const navbar=document.getElementById('navbar');window.addEventListener('scroll',()=>{if(window.scrollY>50){navbar.classList.add('scrolled')}else{navbar.classList.remove('scrolled')}});const container=document.getElementById('carouselContainer');const track=document.getElementById('track');const prevBtn=document.getElementById('prevBtn');const nextBtn=document.getElementById('nextBtn');const cards=Array.from(track.children);cards.forEach(card=>{const clone=card.cloneNode(!0);track.appendChild(clone)});nextBtn.addEventListener('click',()=>{const cardWidth=track.firstElementChild.offsetWidth+24;container.scrollBy({left:cardWidth,behavior:'smooth'});if(container.scrollLeft>=(container.scrollWidth-container.clientWidth)-10){setTimeout(()=>{container.scrollTo({left:0,behavior:'instant'})},500)}});prevBtn.addEventListener('click',()=>{const cardWidth=track.firstElementChild.offsetWidth+24;if(container.scrollLeft<=0){container.scrollTo({left:container.scrollWidth/2,behavior:'instant'});setTimeout(()=>{container.scrollBy({left:-cardWidth,behavior:'smooth'})},10)}else{container.scrollBy({left:-cardWidth,behavior:'smooth'})}})